1: // NEX Arm 3-camera eval frontend.
2: // Auto-detects the three USB cameras by label / USB vendor ID and never opens the
3: // built-in FaceTime camera.
4: 
5: const CAMERAS = [
6:   {
7:     key: "wrist",
8:     name: "Robot Wrist (USB)",
9:     // icspring UVC camera, VendorID 13030 = 0x32e6, ProductID 36869 = 0x9005
10:     match: (l) => /icspring/i.test(l) || /32e6:9005/i.test(l),
11:   },
12:   {
13:     key: "realsense",
14:     name: "RealSense D415 (RGB)",
15:     // Intel 0x8086, ProductID 2771 = 0x0ad3
16:     match: (l) => /realsense/i.test(l) || /8086:0ad3/i.test(l),
17:   },
18:   {
19:     key: "logitech",
20:     name: "Logitech C922",
21:     // Logitech 0x046d, ProductID 2140 = 0x085c
22:     match: (l) => /c922|logitech/i.test(l) || /046d:/i.test(l),
23:   },
24: ];
25: 
26: const isExcluded = (label) => /facetime|built-in|integrated/i.test(label);
27: 
28: const grid = document.getElementById("grid");
29: const tpl = document.getElementById("tileTpl");
30: const statusEl = document.getElementById("status");
31: const resSel = document.getElementById("resolution");
32: const fpsSel = document.getElementById("fps");
33: 
34: const tiles = {}; // key -> { cfg, el, video, select, stream, deviceId }
35: let devices = [];
36: 
37: function setStatus(t) { statusEl.textContent = t; }
38: 
39: function buildTiles() {
40:   for (const cfg of CAMERAS) {
41:     const el = tpl.content.firstElementChild.cloneNode(true);
42:     el.querySelector(".name").textContent = cfg.name;
43:     const t = {
44:       cfg, el,
45:       video: el.querySelector("video"),
46:       select: el.querySelector(".device"),
47:       msg: el.querySelector(".msg"),
48:       stats: el.querySelector(".stats"),
49:       label: el.querySelector(".label"),
50:       stream: null, deviceId: null,
51:     };
52:     t.select.addEventListener("change", () => startTile(t, t.select.value));
53:     el.querySelector(".snap").addEventListener("click", () => snapshot(t));
54:     el.querySelector(".full").addEventListener("click", () => t.video.requestFullscreen?.());
55:     grid.appendChild(el);
56:     tiles[cfg.key] = t;
57:   }
58: }
59: 
60: async function unlockLabels() {
61:   // Device labels are hidden until camera permission is granted once.
62:   const probe = await navigator.mediaDevices.enumerateDevices();
63:   if (probe.some((d) => d.kind === "videoinput" && d.label)) return;
64:   // Ask for a non-FaceTime camera if possible; any camera unlocks labels.
65:   const s = await navigator.mediaDevices.getUserMedia({ video: true });
66:   s.getTracks().forEach((tr) => tr.stop());
67: }
68: 
69: async function refreshDevices() {
70:   const all = await navigator.mediaDevices.enumerateDevices();
71:   devices = all.filter((d) => d.kind === "videoinput" && !isExcluded(d.label));
72: }
73: 
74: function fillSelect(t) {
75:   t.select.innerHTML = "";
76:   const none = new Option("— none —", "");
77:   t.select.add(none);
78:   for (const d of devices) t.select.add(new Option(d.label || d.deviceId.slice(0, 8), d.deviceId));
79:   t.select.value = t.deviceId || "";
80: }
81: 
82: function stopTile(t) {
83:   t.stream?.getTracks().forEach((tr) => tr.stop());
84:   t.stream = null;
85:   t.video.srcObject = null;
86: }
87: 
88: async function startTile(t, deviceId) {
89:   stopTile(t);
90:   t.deviceId = deviceId || null;
91:   t.msg.textContent = "";
92:   t.stats.textContent = "";
93:   if (!deviceId) {
94:     t.msg.textContent = `${t.cfg.name} not found. Is it plugged in?`;
95:     t.label.textContent = "";
96:     return;
97:   }
98:   const [w, h] = resSel.value.split("x").map(Number);
99:   const fps = Number(fpsSel.value);
100:   try {
101:     t.stream = await navigator.mediaDevices.getUserMedia({
102:       audio: false,
103:       video: {
104:         deviceId: { exact: deviceId },
105:         width: { ideal: w }, height: { ideal: h }, frameRate: { ideal: fps },
106:       },
107:     });
108:     t.video.srcObject = t.stream;
109:     const dev = devices.find((d) => d.deviceId === deviceId);
110:     t.label.textContent = dev?.label || deviceId;
111:   } catch (e) {
112:     t.msg.textContent = `Failed to open camera: ${e.name} — ${e.message}`;
113:   }
114: }
115: 
116: function autoAssign() {
117:   const used = new Set();
118:   for (const cfg of CAMERAS) {
119:     const d = devices.find((d) => !used.has(d.deviceId) && cfg.match(d.label));
120:     tiles[cfg.key].deviceId = d?.deviceId || null;
121:     if (d) used.add(d.deviceId);
122:   }
123: }
124: 
125: async function startAll() {
126:   for (const t of Object.values(tiles)) fillSelect(t);
127:   // Open sequentially; opening several UVC cameras at once can fail on macOS.
128:   for (const t of Object.values(tiles)) await startTile(t, t.deviceId);
129:   const live = Object.values(tiles).filter((t) => t.stream).length;
130:   setStatus(`${live}/3 cameras live · FaceTime excluded`);
131: }
132: 
133: // --- Stats overlay (resolution + measured FPS) ---
134: function startStatsLoop() {
135:   for (const t of Object.values(tiles)) {
136:     let frames = 0, last = performance.now();
137:     const tick = () => {
138:       frames++;
139:       const now = performance.now();
140:       if (now - last >= 1000) {
141:         if (t.stream) {
142:           const fps = (frames * 1000) / (now - last);
143:           t.stats.textContent = `${t.video.videoWidth}×${t.video.videoHeight} · ${fps.toFixed(1)} fps`;
144:         }
145:         frames = 0; last = now;
146:       }
147:       t.video.requestVideoFrameCallback(tick);
148:     };
149:     if ("requestVideoFrameCallback" in HTMLVideoElement.prototype) t.video.requestVideoFrameCallback(tick);
150:   }
151: }
152: 
153: // --- Snapshot / record ---
154: const stamp = () => new Date().toISOString().replace(/[:.]/g, "-");
155: 
156: function download(blob, filename) {
157:   const a = document.createElement("a");
158:   a.href = URL.createObjectURL(blob);
159:   a.download = filename;
160:   a.click();
161:   setTimeout(() => URL.revokeObjectURL(a.href), 5000);
162: }
163: 
164: function snapshot(t, ts = stamp()) {
165:   if (!t.stream || !t.video.videoWidth) return;
166:   const c = document.createElement("canvas");
167:   c.width = t.video.videoWidth;
168:   c.height = t.video.videoHeight;
169:   c.getContext("2d").drawImage(t.video, 0, 0);
170:   c.toBlob((b) => download(b, `${t.cfg.key}_${ts}.png`), "image/png");
171: }
172: 
173: let recorders = [];
174: const recBtn = document.getElementById("recordAll");
175: 
176: function toggleRecord() {
177:   if (recorders.length) {
178:     recorders.forEach((r) => r.stop());
179:     recorders = [];
180:     recBtn.textContent = "● Record all";
181:     recBtn.classList.remove("recording");
182:     return;
183:   }
184:   const ts = stamp();
185:   const mime = ["video/mp4", "video/webm;codecs=vp9", "video/webm"].find((m) => MediaRecorder.isTypeSupported(m));
186:   const ext = mime?.startsWith("video/mp4") ? "mp4" : "webm";
187:   for (const t of Object.values(tiles)) {
188:     if (!t.stream) continue;
189:     const chunks = [];
190:     const r = new MediaRecorder(t.stream, mime ? { mimeType: mime } : undefined);
191:     r.ondataavailable = (e) => e.data.size && chunks.push(e.data);
192:     r.onstop = () => download(new Blob(chunks, { type: r.mimeType }), `${t.cfg.key}_${ts}.${ext}`);
193:     r.start(1000);
194:     recorders.push(r);
195:   }
196:   if (recorders.length) {
197:     recBtn.textContent = "■ Stop recording";
198:     recBtn.classList.add("recording");
199:   }
200: }
201: 
202: // --- Wire up ---
203: document.getElementById("restart").addEventListener("click", startAll);
204: document.getElementById("snapAll").addEventListener("click", () => {
205:   const ts = stamp();
206:   Object.values(tiles).forEach((t) => snapshot(t, ts));
207: });
208: recBtn.addEventListener("click", toggleRecord);
209: resSel.addEventListener("change", startAll);
210: fpsSel.addEventListener("change", startAll);
211: 
212: navigator.mediaDevices.addEventListener("devicechange", async () => {
213:   await refreshDevices();
214:   for (const t of Object.values(tiles)) {
215:     if (t.deviceId && !devices.some((d) => d.deviceId === t.deviceId)) t.deviceId = null;
216:   }
217:   // Fill empty slots with newly plugged-in cameras.
218:   const used = new Set(Object.values(tiles).map((t) => t.deviceId).filter(Boolean));
219:   for (const t of Object.values(tiles)) {
220:     if (t.deviceId) continue;
221:     const d = devices.find((d) => !used.has(d.deviceId) && t.cfg.match(d.label));
222:     if (d) { t.deviceId = d.deviceId; used.add(d.deviceId); }
223:   }
224:   setStatus("Devices changed — restarting…");
225:   startAll();
226: });
227: 
228: (async function main() {
229:   buildTiles();
230:   if (!navigator.mediaDevices?.getUserMedia) {
231:     setStatus("Camera API unavailable. Open via http://localhost (not file://).");
232:     return;
233:   }
234:   try {
235:     setStatus("Requesting camera permission…");
236:     await unlockLabels();
237:     await refreshDevices();
238:     autoAssign();
239:     await startAll();
240:     startStatsLoop();
241:   } catch (e) {
242:     setStatus(`Error: ${e.name} — ${e.message}`);
243:   }
244: })();

